#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
namespace PinPop {
 public sealed class AuditFixesReview:MonoBehaviour {
  [Serializable]class Saved {public string key,value;public bool integer,exists;}
  [Serializable]class Result {public int passed,failed;public bool complete,restored;public List<string> checks=new List<string>();}
  public static bool Active {get;private set;}
  EventSystem events;bool eventsEnabled;
  List<Saved> saved=new List<Saved>();Result result=new Result();PinPopGame game;string folder;RenderTexture screen;bool restored;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){string request=Path.Combine(Application.persistentDataPath,"AuditFixesReview.request");if(Array.IndexOf(Environment.GetCommandLineArgs(),"-audit-fixes-test")<0&&!File.Exists(request))return;if(File.Exists(request))File.Delete(request);Active=true;new GameObject("Audit fixes review").AddComponent<AuditFixesReview>();}
  void Check(bool ok,string text){if(ok)result.passed++;else result.failed++;result.checks.Add((ok?"PASS: ":"FAIL: ")+text);Debug.Log(result.checks[result.checks.Count-1]);Save();}
  void Remember(string key,bool integer){saved.Add(new Saved{key=key,integer=integer,exists=PlayerPrefs.HasKey(key),value=integer?PlayerPrefs.GetInt(key).ToString():PlayerPrefs.GetString(key)});}
  IEnumerator Start(){
   folder=Environment.GetEnvironmentVariable("PINPOP_QA_DIR")??Path.Combine(Application.persistentDataPath,"AuditFixesReview");Directory.CreateDirectory(folder);Application.logMessageReceived+=Log;
   while((game=FindFirstObjectByType<PinPopGame>())==null||!game.Initialized||PinPopSplash.Visible)yield return null;
   events=EventSystem.current;if(events!=null){eventsEnabled=events.enabled;events.enabled=false;}
   foreach(string k in new[]{PinPopEconomy.SaveKey,PinPopAdventure.SaveKey,GameLocalization.PreferenceKey})Remember(k,false);foreach(string k in new[]{"Level","Coins","SwapCredits","ReducedMotion","Muted",PinPopHUD.TutorialSeenKey})Remember(k,true);
   GameLocalization.SetPreference("tr");PlayerPrefs.SetInt("ReducedMotion",1);PlayerPrefs.SetInt(PinPopHUD.TutorialSeenKey,1);Size(1170,2532);yield return new WaitForSecondsRealtime(.3f);
   Board(4);yield return null;int initial=IceMaterials();for(int n=0;n<20;n++){game.LoadLevel(4);yield return null;}GC.Collect();yield return null;int after=IceMaterials();Check(initial==1&&after==initial,"Ice materials remain shared after twenty restarts: "+initial+" → "+after);
   Board(2);yield return null;Physics.SyncTransforms();game.SetLaunchX(-1.75f);var target=new Vector3(-1.75f,.4f,2);var origin=game.LaunchPosition;var direction=(target-origin).normalized;var prediction=game.PredictRoll(target,1,origin);RaycastHit hit;bool contact=Physics.SphereCast(origin,.39f,direction,out hit,10);float predicted=Vector3.Dot(prediction.Point-origin,direction);Check(contact&&game.Adventure.IsObstacle(hit.collider)&&Mathf.Abs(predicted-hit.distance)<.02f,"Aim ends at first bumper contact: physical="+hit.distance+", preview="+predicted);
   var anchor=(Vector2)game.Camera.WorldToScreenPoint(origin);game.BeginPullForVerification(anchor);game.UpdatePull(anchor+Vector2.down*140*game.Camera.pixelHeight/1000);Capture("aim-blocked");game.CancelPull();
   Board(8);yield return null;float previous=-1;bool moved=false,accurate=true;for(int n=0;n<30;n++){var gate=GameObject.Find("Moving festival gate");game.SetLaunchX(gate.transform.position.x);origin=game.LaunchPosition;prediction=game.PredictRoll(origin+Vector3.forward*10,1,origin);contact=Physics.SphereCast(origin,.39f,Vector3.forward,out hit,10);accurate&=contact&&game.Adventure.IsObstacle(hit.collider)&&Mathf.Abs(prediction.Point.z-origin.z-hit.distance)<.03f;if(previous>=0)moved|=Mathf.Abs(previous-gate.transform.position.x)>.001f;previous=gate.transform.position.x;yield return new WaitForFixedUpdate();}Check(moved&&accurate,"Moving gate prediction follows its current physical location");
   foreach(int count in new[]{12,48}){
    Board(11);yield return null;game.PrepareShotColor(-1);for(int i=0;i<count;i++)Drop(game.Pins[i]);yield return null;Time.timeScale=0;float before=game.MatchTray.Items[0].Age;yield return new WaitForSecondsRealtime(.15f);Check(game.MatchTray.Items[0].Age==before,"Ordinary pause freezes collection flights");
    bool fits=true,queued=false;int peakCombo=0;for(int step=0;step<85&&!game.MatchTray.Empty;step++){game.MatchTray.Tick(.05f);yield return null;fits&=ArrivedFit();foreach(var item in game.MatchTray.Items)if(!item.Presented){queued=true;fits&=item.Age==0;}int labels=0;foreach(var text in FindObjectsByType<Text>(FindObjectsSortMode.None))if(text.name=="Triple match")labels++;peakCombo=Mathf.Max(peakCombo,labels);if(step==10)Capture("multi-collect-"+count);if(step==17)Capture("combo-"+count);}
    Check(fits,"All presented figures stay inside the tray during "+count+" clears");Check(game.MatchTray.Empty&&game.MatchTray.MatchCount==count/3&&!game.TrayOverflow,"All "+count+" figures finish exactly once without false capacity loss");Check(peakCombo==1,"Only one readable combo label exists for "+count+" clears");if(count==48)Check(queued,"Large clear queues reservations until a visible well is free");
   }
   Board(11);yield return null;int coins=game.Coins,moves=game.Moves;game.PrepareShotColor(-1);for(int c=0;c<5;c++){var pins=game.Pins.FindAll(x=>x.ColorId==c);Drop(pins[0]);Drop(pins[1]);}yield return null;
   Check(game.TrayOverflow&&game.Busy&&game.Paused&&!game.Finished&&!game.Hud.ResultVisible,"Capacity loss freezes gameplay but waits for visible collection");Check(!game.Shoot(Vector3.forward)&&!game.Swap(),"Overflow settlement rejects new shots and swaps");game.Hud.ShowSettings();Check(!game.Hud.SettingsVisible,"Overflow settlement cannot be interrupted by settings");
   float began=Time.realtimeSinceStartup;while(!game.Finished&&Time.realtimeSinceStartup-began<4)yield return null;Check(game.Finished&&!game.Won&&game.MatchTray.Items.TrueForAll(x=>x.Arrived&&x.Presented)&&game.MatchTray.LiveCount==10,"Overflow result opens after all ten figures have visibly landed");Check(game.Coins==coins&&game.Moves==moves,"Overflow settlement never spends currency or moves");
   foreach(var size in new[]{new Vector2Int(320,568),new Vector2Int(390,844),new Vector2Int(1170,2532)}){Size(size.x,size.y);yield return new WaitForSecondsRealtime(.3f);var card=Bounds(GameObject.Find("Recovery border").GetComponent<RectTransform>());foreach(string name in new[]{"CONTINUE","RESULT_HOME"}){var b=Bounds(GameObject.Find(name).GetComponent<RectTransform>());Check(b.yMin>=card.yMin&&b.yMax<=card.yMax,"Overflow button fits its card: "+name+" "+size.x);}Check(!GameObject.Find("resultReward").GetComponent<Text>().text.Contains("1 kez")&&GameObject.Find("WATCH_VIDEO")==null,"Overflow result has no irrelevant video offer");Capture("overflow-"+size.x);}
   Size(1170,2532);Board(11);yield return null;game.PrepareShotColor(-1);for(int c=0;c<5;c++){var pins=game.Pins.FindAll(x=>x.ColorId==c);Drop(pins[0]);Drop(pins[1]);}yield return null;Board(0);yield return new WaitForSecondsRealtime(1);Check(!game.TrayOverflow&&!game.Finished&&!game.Hud.ResultVisible,"Restart cancels the pending overflow result");
   foreach(bool home in new[]{false,true}){Board(home?0:11);game.SetMenu(home);if(home)game.Hud.ShowHome();int attempt=game.AttemptId;coins=game.Coins;moves=game.Moves;int[] queue=game.Queue.ToArray();game.Hud.ShowSettings();yield return new WaitForSecondsRealtime(.25f);Check(Click("HELP_SETTINGS"),"Pointer reaches how-to replay from "+(home?"home":"game")+" settings");yield return new WaitForSecondsRealtime(.25f);Check(game.Hud.HelpVisible&&game.Paused,"Replayed how-to stays paused");Check(GameObject.Find("How to play").GetComponentsInChildren<Button>().Length==1,"How-to retains one close cross without extra Done");Capture(home?"help-home":"help-game");Check(Click("HELP_CLOSE"),"Pointer reaches how-to close cross");yield return null;Check(game.Hud.SettingsVisible&&game.Paused,"How-to cross returns to paused settings");Check(game.AttemptId==attempt&&game.Moves==moves&&game.Coins==coins&&SameQueue(queue),"Replay preserves attempt, moves, queue and wallet");game.Hud.CloseOverlays();Check(!game.Paused&&game.InMenu==home,"Closing settings restores the previous game/menu context");}
   Restore();result.complete=true;Active=false;if(events!=null)events.enabled=eventsEnabled;Save();Application.Quit(result.failed==0?0:1);
  }
  bool SameQueue(int[] q){if(q.Length!=game.Queue.Count)return false;for(int i=0;i<q.Length;i++)if(q[i]!=game.Queue[i])return false;return true;}
  void Board(int level){game.GetComponent<AdventureHUD>().Close();game.Hud.HideResult();game.Hud.CloseOverlays();game.SetMenu(false);game.LoadLevel(level);game.Hud.ShowGame();}
  void Drop(PinTarget pin){pin.Body.position=new Vector3(pin.Body.position.x,-2,pin.Body.position.z);}
  int IceMaterials(){int count=0;foreach(var m in Resources.FindObjectsOfTypeAll<Material>())if(m.name=="Shared pin ice")count++;return count;}
  bool ArrivedFit(){var bounds=Bounds(GameObject.Find("Collection tray").GetComponent<RectTransform>());foreach(var item in game.MatchTray.Items)if(item.Presented&&item.Arrived){var icon=GameObject.Find("Collected color "+item.Id);if(icon==null)return false;var b=Bounds(icon.GetComponent<RectTransform>());if(b.xMin<bounds.xMin-.5f||b.xMax>bounds.xMax+.5f)return false;}return true;}
  bool Click(string name){Canvas.ForceUpdateCanvases();var expected=GameObject.Find(name);if(expected==null)return false;var evt=new PointerEventData(events){position=Bounds(expected.GetComponent<RectTransform>()).center,button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();events.RaycastAll(evt,hits);var target=hits.Count==0?null:ExecuteEvents.GetEventHandler<IPointerClickHandler>(hits[0].gameObject);if(target==expected)ExecuteEvents.Execute(target,evt,ExecuteEvents.pointerClickHandler);return target==expected;}
  Rect Bounds(RectTransform rect){var c=new Vector3[4];rect.GetWorldCorners(c);var a=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,c[0]);var b=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,c[2]);return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
  void Size(int w,int h){CrispUI.ReviewSize=new Vector2Int(w,h);CrispUI.ReviewSafeArea=w==1170?new Rect(0,102,w,h-243):new Rect(0,0,w,h);if(screen!=null){screen.Release();Destroy(screen);}screen=new RenderTexture(w,h,24);screen.Create();game.Camera.targetTexture=screen;game.Hud.UICamera.targetTexture=screen;}
  void Capture(string name){Canvas.ForceUpdateCanvases();var old=RenderTexture.active;game.Camera.Render();game.Hud.UICamera.Render();RenderTexture.active=screen;var tex=new Texture2D(screen.width,screen.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,screen.width,screen.height),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),tex.EncodeToPNG());Destroy(tex);RenderTexture.active=old;}
  void Log(string message,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){Check(false,message+"\n"+stack);Restore();Save();Application.Quit(1);}}
  void Save(){File.WriteAllText(Path.Combine(folder,"verification.json"),JsonUtility.ToJson(result,true));}
  void Restore(){if(restored)return;restored=true;foreach(var x in saved){if(!x.exists)PlayerPrefs.DeleteKey(x.key);else if(x.integer)PlayerPrefs.SetInt(x.key,int.Parse(x.value));else PlayerPrefs.SetString(x.key,x.value);}PlayerPrefs.Save();result.restored=true;}
  void OnApplicationQuit(){Restore();}void OnDestroy(){Active=false;if(events!=null)events.enabled=eventsEnabled;Application.logMessageReceived-=Log;Restore();CrispUI.ReviewSize=null;CrispUI.ReviewSafeArea=null;}
 }
}
#endif
